'use client'

// React Imports
import { useState } from 'react'

// Next Imports
import { usePathname } from 'next/navigation'

// MUI Imports
import Box from '@mui/material/Box'
import Drawer from '@mui/material/Drawer'
import List from '@mui/material/List'
import ListItem from '@mui/material/ListItem'
import ListItemButton from '@mui/material/ListItemButton'
import ListItemIcon from '@mui/material/ListItemIcon'
import ListItemText from '@mui/material/ListItemText'
import ListSubheader from '@mui/material/ListSubheader'
import Divider from '@mui/material/Divider'
import IconButton from '@mui/material/IconButton'
import useMediaQuery from '@mui/material/useMediaQuery'
import type { Theme } from '@mui/material/styles'

// Component Imports
import Logo from '@components/layout/shared/Logo'

const SIDEBAR_WIDTH = 260

type MenuItem = {
  label?: string
  icon?: string
  href?: string
  section?: string
}

const menuItems: MenuItem[] = [
  { section: 'Dashboards' },
  { label: 'Analytics', icon: 'tabler-chart-pie-2', href: '/dashboards/analytics' },
  { section: 'Property Management' },
  { label: 'Properties', icon: 'tabler-building' },
  { label: 'Tenants', icon: 'tabler-users' },
  { label: 'Leases', icon: 'tabler-file-text' },
  { label: 'Maintenance', icon: 'tabler-tool' },
  { section: 'Finance' },
  { label: 'Payments', icon: 'tabler-credit-card' },
  { label: 'Invoices', icon: 'tabler-receipt' },
  { label: 'Reports', icon: 'tabler-chart-bar' },
  { section: 'Settings' },
  { label: 'Account Settings', icon: 'tabler-settings' },
  { label: 'Roles & Permissions', icon: 'tabler-lock' }
]

type Props = {
  open: boolean
  onClose: () => void
  onToggle: () => void
}

const Navigation = ({ open, onClose, onToggle }: Props) => {
  const pathname = usePathname()
  const isDesktop = useMediaQuery((theme: Theme) => theme.breakpoints.up('lg'))

  const sidebarContent = (
    <Box className='flex flex-col bs-full'>
      {/* Header */}
      <Box className='flex items-center justify-between pli-5 plb-4'>
        <Logo />
        {!isDesktop && (
          <IconButton onClick={onClose} size='small'>
            <i className='tabler-x text-xl' />
          </IconButton>
        )}
      </Box>
      <Divider />

      {/* Menu */}
      <List component='nav' className='flex-1 overflow-y-auto pbs-2'>
        {menuItems.map((item, index) => {
          if (item.section) {
            return (
              <ListSubheader
                key={index}
                className='bg-transparent text-textDisabled uppercase text-xs font-semibold tracking-wider pbs-4 pbe-1'
              >
                {item.section}
              </ListSubheader>
            )
          }

          const isActive = item.href && pathname.includes(item.href)

          return (
            <ListItem key={index} disablePadding className='pli-3 pbe-0.5'>
              <ListItemButton
                className='rounded'
                selected={!!isActive}
                sx={{
                  '&.Mui-selected': {
                    backgroundColor: 'var(--mui-palette-primary-lightOpacity)',
                    color: 'var(--mui-palette-primary-main)',
                    '& .MuiListItemIcon-root': {
                      color: 'var(--mui-palette-primary-main)'
                    },
                    '&:hover': {
                      backgroundColor: 'var(--mui-palette-primary-lightOpacity)'
                    }
                  }
                }}
              >
                <ListItemIcon sx={{ minWidth: 36 }}>
                  <i className={`${item.icon} text-xl`} />
                </ListItemIcon>
                <ListItemText primary={item.label} primaryTypographyProps={{ variant: 'body2' }} />
              </ListItemButton>
            </ListItem>
          )
        })}
      </List>
    </Box>
  )

  if (isDesktop) {
    return (
      <Box
        component='aside'
        sx={{
          width: SIDEBAR_WIDTH,
          flexShrink: 0,
          borderInlineEnd: '1px solid var(--mui-palette-divider)',
          backgroundColor: 'var(--mui-palette-background-paper)'
        }}
      >
        <Box sx={{ position: 'sticky', top: 0, height: '100dvh', overflow: 'hidden' }}>{sidebarContent}</Box>
      </Box>
    )
  }

  return (
    <Drawer
      open={open}
      onClose={onClose}
      PaperProps={{ sx: { width: SIDEBAR_WIDTH } }}
    >
      {sidebarContent}
    </Drawer>
  )
}

export default Navigation
